/// The six generated route modes for an exact `(profile, wire id)` pair.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RouteMode {
    /// Same wire id and complete nested graph.
    Direct,
    /// Different wire id, identical body.
    Retag,
    /// Body, projection or nested graph differs.
    Rewrite,
    /// An explicit policy decision applies.
    Policy,
    /// Present only in the profile.
    ProfileOnly,
    /// Absent or rejected.
    Unavailable,
}

impl RouteMode {
    /// Returns the lowercase identifier.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            RouteMode::Direct => "direct",
            RouteMode::Retag => "retag",
            RouteMode::Rewrite => "rewrite",
            RouteMode::Policy => "policy",
            RouteMode::ProfileOnly => "profile-only",
            RouteMode::Unavailable => "unavailable",
        }
    }
}

/// One explicit `(profile, wire id)` route.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Route {
    /// Profile layer.
    pub profile: i32,
    /// Wire identifier in that profile.
    pub wire_id: u32,
    /// Semantic identity.
    pub semantic: SemanticId,
    /// Route mode.
    pub mode: RouteMode,
}

