/// Looks up the explicit route for an exact `(profile, wire id)` pair.
#[must_use]
pub fn lookup_route(profile: Profile, wire_id: u32) -> Option<Route> {
    ROUTES
        .iter()
        .find(|route| route.profile == profile.layer && route.wire_id == wire_id)
        .copied()
}

/// Resolves the semantic identity of a wire id in a profile.
#[must_use]
pub fn semantic_for_wire_id(profile: Profile, wire_id: u32) -> Option<SemanticId> {
    lookup_route(profile, wire_id).map(|route| route.semantic)
}

/// Resolves the wire identifier of a semantic identity in a profile.
#[must_use]
pub fn wire_id(profile: Profile, semantic: SemanticId) -> Option<u32> {
    ROUTES
        .iter()
        .find(|route| route.profile == profile.layer && route.semantic == semantic)
        .map(|route| route.wire_id)
}

