pub fn decode_channel_participants_filter_profile(
    profile: Profile,
    id: u32,
    __d: &mut Decoder<'_>,
) -> Result<rtd_tg::ChannelParticipantsFilter, AdmitError> {
    let route =
        lookup_route(profile, id).ok_or(AdmitError::Decode(::rtd_bin::Error::UnexpectedId {
            id,
            expected: 0,
        }))?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => {
            Ok(rtd_tg::ChannelParticipantsFilter::decode_with_id(
                __d,
                canonical_wire_id(route.semantic).unwrap_or(id),
            )?)
        }
        RouteMode::Rewrite => match route.semantic.0 {
            0xe85531254e8ef47e => Ok(rtd_tg::ChannelParticipantsFilter::ChannelParticipantsAdmins),
            0x79573f2f6661dbb1 => {
                let q: ::std::string::String = __d.take_string()?.to_owned();
                Ok(rtd_tg::ChannelParticipantsFilter::ChannelParticipantsBanned { q })
            }
            0x36e823db5a762d36 => Ok(rtd_tg::ChannelParticipantsFilter::ChannelParticipantsBots),
            0xd664a350a59256c5 => {
                let q: ::std::string::String = __d.take_string()?.to_owned();
                Ok(rtd_tg::ChannelParticipantsFilter::ChannelParticipantsContacts { q })
            }
            0x7ffaa55554d2d03b => {
                let q: ::std::string::String = __d.take_string()?.to_owned();
                Ok(rtd_tg::ChannelParticipantsFilter::ChannelParticipantsKicked { q })
            }
            0x1513399412173825 => {
                let flags = __d.take_u32()?;
                let q: Option<::std::string::String> = if flags & (1u32 << 0) != 0 {
                    Some(__d.take_string()?.to_owned())
                } else {
                    None
                };
                let top_msg_id: Option<i32> = if flags & (1u32 << 1) != 0 {
                    Some(__d.take_i32()?)
                } else {
                    None
                };
                Ok(
                    rtd_tg::ChannelParticipantsFilter::ChannelParticipantsMentions {
                        flags,
                        q,
                        top_msg_id,
                    },
                )
            }
            0xf040e9a21ab94b21 => Ok(rtd_tg::ChannelParticipantsFilter::ChannelParticipantsRecent),
            0x4754539f7239516d => {
                let q: ::std::string::String = __d.take_string()?.to_owned();
                Ok(rtd_tg::ChannelParticipantsFilter::ChannelParticipantsSearch { q })
            }
            _ => Err(AdmitError::UnsupportedRoute(route)),
        },
        _ => Err(AdmitError::UnsupportedRoute(route)),
    }
}

