            let anonymous: bool = flags & (1u32 << 10) != 0;
            let manage_call: bool = flags & (1u32 << 11) != 0;
            let other: bool = flags & (1u32 << 12) != 0;
            let manage_topics: bool = flags & (1u32 << 13) != 0;
