pub fn encode_chat_admin_with_invites_profile(
    profile: Profile,
    value: &rtd_tg::ChatAdminWithInvites,
    __w: &mut Writer,
) -> Result<(), ProjectionError> {
    let route = lookup_route_semantic(profile, SemanticId(0x6cb2aeb76b1e165b)).ok_or(
        ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0xf2ecef23,
        },
    )?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => {
            __w.put_u32(route.wire_id);
            let rtd_tg::ChatAdminWithInvites {
                admin_id,
                invites_count,
                revoked_invites_count,
            } = value;
            __w.put_i64(*admin_id);
            __w.put_i32(*invites_count);
            __w.put_i32(*revoked_invites_count);
            Ok(())
        }
        RouteMode::Rewrite => {
            __w.put_u32(route.wire_id);
            let rtd_tg::ChatAdminWithInvites {
                admin_id,
                invites_count,
                revoked_invites_count,
            } = value;
            __w.put_i64(*admin_id);
            __w.put_i32(*invites_count);
            __w.put_i32(*revoked_invites_count);
            Ok(())
        }
        _ => Err(ProjectionError::RouteNotEmitted(route)),
    }
}

