            let offline_idle_timeout_ms: i32 = __d.take_i32()?;
            let online_cloud_timeout_ms: i32 = __d.take_i32()?;
            let notify_cloud_delay_ms: i32 = __d.take_i32()?;
            let notify_default_delay_ms: i32 = __d.take_i32()?;
