pub fn decode_document_profile(
    profile: Profile,
    id: u32,
    __d: &mut Decoder<'_>,
) -> Result<rtd_tg::Document, AdmitError> {
    let route =
        lookup_route(profile, id).ok_or(AdmitError::Decode(::rtd_bin::Error::UnexpectedId {
            id,
            expected: 0,
        }))?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => Ok(rtd_tg::Document::decode_with_id(
            __d,
            canonical_wire_id(route.semantic).unwrap_or(id),
        )?),
        RouteMode::Rewrite => match route.semantic.0 {
            0x3ab01cfaf9270ae4 => {
                let flags = __d.take_u32()?;
                let id: i64 = __d.take_i64()?;
                let access_hash: i64 = __d.take_i64()?;
                let file_reference: ::std::vec::Vec<u8> = __d.take_bytes()?.to_vec();
                let date: i32 = __d.take_i32()?;
                let mime_type: ::std::string::String = __d.take_string()?.to_owned();
                let size: i64 = __d.take_i64()?;
                let thumbs: Option<::std::vec::Vec<rtd_tg::PhotoSize>> = if flags & (1u32 << 0) != 0
                {
                    Some({
                        let n = __d.take_vector_header()?;
                        let mut items =
                            ::std::vec::Vec::with_capacity(::rtd_bin::preallocate_len(n));
                        for _ in 0..n {
                            items.push({
                                __d.enter()?;
                                let value = {
                                    let __id = __d.take_u32()?;
                                    decode_photo_size_profile(profile, __id, __d)?
                                };
                                __d.leave();
                                value
                            });
                        }
                        items
                    })
                } else {
                    None
                };
                let video_thumbs: Option<::std::vec::Vec<rtd_tg::VideoSize>> =
                    if flags & (1u32 << 1) != 0 {
                        Some({
                            let n = __d.take_vector_header()?;
                            let mut items =
                                ::std::vec::Vec::with_capacity(::rtd_bin::preallocate_len(n));
                            for _ in 0..n {
                                items.push({
                                    __d.enter()?;
                                    let value = {
                                        let __id = __d.take_u32()?;
                                        decode_video_size_profile(profile, __id, __d)?
                                    };
                                    __d.leave();
                                    value
                                });
                            }
                            items
                        })
                    } else {
                        None
                    };
                let dc_id: i32 = __d.take_i32()?;
                let attributes: ::std::vec::Vec<rtd_tg::DocumentAttribute> = {
                    let n = __d.take_vector_header()?;
                    let mut items = ::std::vec::Vec::with_capacity(::rtd_bin::preallocate_len(n));
                    for _ in 0..n {
                        items.push({
                            __d.enter()?;
                            let value = {
                                let __id = __d.take_u32()?;
                                decode_document_attribute_profile(profile, __id, __d)?
                            };
                            __d.leave();
                            value
                        });
                    }
                    items
                };
                Ok(rtd_tg::Document::Document {
                    flags,
                    id,
                    access_hash,
                    file_reference,
                    date,
                    mime_type,
                    size,
                    thumbs,
                    video_thumbs,
                    dc_id,
                    attributes,
                })
            }
            0x45767920831412e2 => {
                let id: i64 = __d.take_i64()?;
                Ok(rtd_tg::Document::DocumentEmpty { id })
            }
            _ => Err(AdmitError::UnsupportedRoute(route)),
        },
        _ => Err(AdmitError::UnsupportedRoute(route)),
    }
}

