            let route = lookup_route_semantic(profile, SemanticId(0xcbecc3b8b06bf2ed)).ok_or(
                ProjectionError::Unrepresentable {
                    layer: profile.layer,
                    wire_id: 0x1b0c841a,
                },
            )?;
