pub fn encode_emoji_keywords_difference_profile(
    profile: Profile,
    value: &rtd_tg::EmojiKeywordsDifference,
    __w: &mut Writer,
) -> Result<(), ProjectionError> {
    let route = lookup_route_semantic(profile, SemanticId(0xbf83e86e926b4586)).ok_or(
        ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0x5cc761bd,
        },
    )?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => {
            __w.put_u32(route.wire_id);
            let rtd_tg::EmojiKeywordsDifference {
                lang_code,
                from_version,
                version,
                keywords,
            } = value;
            __w.put_string(lang_code.as_str());
            __w.put_i32(*from_version);
            __w.put_i32(*version);
            __w.put_vector_header(keywords.len());
            for item in keywords.iter() {
                item.encode(__w);
            }
            Ok(())
        }
        RouteMode::Rewrite => {
            __w.put_u32(route.wire_id);
            let rtd_tg::EmojiKeywordsDifference {
                lang_code,
                from_version,
                version,
                keywords,
            } = value;
            __w.put_string(lang_code.as_str());
            __w.put_i32(*from_version);
            __w.put_i32(*version);
            let mut __items: ::std::vec::Vec<::std::vec::Vec<u8>> = ::std::vec::Vec::new();
            for item in keywords.iter() {
                let mut __buf = Writer::with_capacity(16);
                match encode_emoji_keyword_profile(profile, item, &mut __buf) {
                    Ok(()) => __items.push(__buf.into_vec()),
                    Err(ProjectionError::Dropped) => {}
                    Err(error) => return Err(error),
                }
            }
            __w.put_vector_header(__items.len());
            for __item in &__items {
                __w.put_raw(__item);
            }
            Ok(())
        }
        _ => Err(ProjectionError::RouteNotEmitted(route)),
    }
}

pub fn decode_emoji_keywords_difference_profile(
    profile: Profile,
    id: u32,
    __d: &mut Decoder<'_>,
) -> Result<rtd_tg::EmojiKeywordsDifference, AdmitError> {
    let route =
        lookup_route(profile, id).ok_or(AdmitError::Decode(::rtd_bin::Error::UnexpectedId {
            id,
            expected: 0,
        }))?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => {
            Ok(rtd_tg::EmojiKeywordsDifference::decode_with_id(
                __d,
                canonical_wire_id(route.semantic).unwrap_or(id),
            )?)
        }
        RouteMode::Rewrite => {
            let lang_code: ::std::string::String = __d.take_string()?.to_owned();
            let from_version: i32 = __d.take_i32()?;
            let version: i32 = __d.take_i32()?;
            let keywords: ::std::vec::Vec<rtd_tg::EmojiKeyword> = {
                let n = __d.take_vector_header()?;
                let mut items = ::std::vec::Vec::with_capacity(::rtd_bin::preallocate_len(n));
                for _ in 0..n {
                    items.push({
                        __d.enter()?;
                        let value = {
                            let __id = __d.take_u32()?;
                            decode_emoji_keyword_profile(profile, __id, __d)?
                        };
                        __d.leave();
                        value
                    });
                }
                items
            };
            Ok(rtd_tg::EmojiKeywordsDifference {
                lang_code,
                from_version,
                version,
                keywords,
            })
        }
        _ => Err(AdmitError::UnsupportedRoute(route)),
    }
}

