fn encode_policy_ephemeral_message_228(
    profile: Profile,
    value: &rtd_tg::EphemeralMessage,
    __w: &mut Writer,
) -> Result<(), ProjectionError> {
    let rtd_tg::EphemeralMessage {
        anchor_msg_id,
        chat_instance,
        date,
        entities,
        from_id,
        id,
        invert_media,
        media,
        message,
        noforwards,
        out,
        peer_id,
        receiver_id,
        reply_markup,
        reply_to,
        rich_message,
        top_msg_id,
        welcome_template,
        ..
    } = value;
    if rich_message.is_some() {
        return Err(ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0xdd27bee9,
        });
    }
    if *welcome_template {
        return Err(ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0xdd27bee9,
        });
    }
    if anchor_msg_id.is_some() {
        return Err(ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0xdd27bee9,
        });
    }
    if chat_instance.is_some() {
        return Err(ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0xdd27bee9,
        });
    }
    if *invert_media {
        return Err(ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0xdd27bee9,
        });
    }
    if *noforwards {
        return Err(ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0xdd27bee9,
        });
    }
    let mut __flags_flags = 0u32;
    if *out {
        __flags_flags |= 1u32 << 0;
    }
    if top_msg_id.is_some() {
        __flags_flags |= 1u32 << 1;
    }
    if entities.is_some() {
        __flags_flags |= 1u32 << 2;
    }
    if media.is_some() {
        __flags_flags |= 1u32 << 3;
    }
    if reply_markup.is_some() {
        __flags_flags |= 1u32 << 4;
    }
    if reply_to.is_some() {
        __flags_flags |= 1u32 << 6;
    }
    __w.put_u32(__flags_flags);
    __w.put_i32(*id);
    encode_peer_profile(profile, from_id, __w)?;
    let __required =
        rtd_layerhooks::ephemeral::require_message_peer(peer_id.is_some(), peer_id.as_deref())?;
    encode_peer_profile(profile, __required, __w)?;
    __w.put_i64(*receiver_id);
    if let Some(value) = top_msg_id {
        __w.put_i32(*value);
    }
    __w.put_i32(*date);
    __w.put_string(message.as_str());
    if let Some(value) = entities {
        let mut __items: ::std::vec::Vec<::std::vec::Vec<u8>> = ::std::vec::Vec::new();
        for item in value.iter() {
            let mut __buf = Writer::with_capacity(16);
            match encode_message_entity_profile(profile, item, &mut __buf) {
                Ok(()) => __items.push(__buf.into_vec()),
                Err(ProjectionError::Dropped) => {}
                Err(error) => return Err(error),
            }
        }
        __w.put_vector_header(__items.len());
        for __item in &__items {
            __w.put_raw(__item);
        }
    }
    if let Some(value) = media {
        encode_message_media_profile(profile, value, __w)?;
    }
    if let Some(value) = reply_markup {
        encode_reply_markup_profile(profile, value, __w)?;
    }
    if let Some(value) = reply_to {
        encode_message_reply_header_profile(profile, value, __w)?;
    }
    Ok(())
}

pub fn decode_ephemeral_message_profile(
    profile: Profile,
    id: u32,
    __d: &mut Decoder<'_>,
) -> Result<rtd_tg::EphemeralMessage, AdmitError> {
    let route =
        lookup_route(profile, id).ok_or(AdmitError::Decode(::rtd_bin::Error::UnexpectedId {
            id,
            expected: 0,
        }))?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => Ok(rtd_tg::EphemeralMessage::decode_with_id(
            __d,
            canonical_wire_id(route.semantic).unwrap_or(id),
        )?),
        RouteMode::Rewrite => {
            let flags = __d.take_u32()?;
            let out: bool = flags & (1u32 << 0) != 0;
            let welcome_template: bool = flags & (1u32 << 5) != 0;
            let invert_media: bool = flags & (1u32 << 7) != 0;
            let noforwards: bool = flags & (1u32 << 12) != 0;
            let id: i32 = __d.take_i32()?;
            let from_id: ::std::boxed::Box<rtd_tg::Peer> = {
                __d.enter()?;
                let value = {
                    let __id = __d.take_u32()?;
                    decode_peer_profile(profile, __id, __d)?
                };
                __d.leave();
                ::std::boxed::Box::new(value)
            };
            let peer_id: Option<::std::boxed::Box<rtd_tg::Peer>> = if flags & (1u32 << 9) != 0 {
                Some({
                    __d.enter()?;
                    let value = {
                        let __id = __d.take_u32()?;
                        decode_peer_profile(profile, __id, __d)?
                    };
                    __d.leave();
                    ::std::boxed::Box::new(value)
                })
            } else {
                None
            };
            let receiver_id: i64 = __d.take_i64()?;
            let top_msg_id: Option<i32> = if flags & (1u32 << 1) != 0 {
                Some(__d.take_i32()?)
            } else {
                None
            };
            let date: i32 = __d.take_i32()?;
            let message: ::std::string::String = __d.take_string()?.to_owned();
            let entities: Option<::std::vec::Vec<rtd_tg::MessageEntity>> = if flags & (1u32 << 2)
                != 0
            {
                Some({
                    let n = __d.take_vector_header()?;
                    let mut items = ::std::vec::Vec::with_capacity(::rtd_bin::preallocate_len(n));
                    for _ in 0..n {
                        items.push({
                            __d.enter()?;
                            let value = {
                                let __id = __d.take_u32()?;
                                decode_message_entity_profile(profile, __id, __d)?
                            };
                            __d.leave();
                            value
                        });
                    }
                    items
                })
            } else {
                None
            };
            let media: Option<::std::boxed::Box<rtd_tg::MessageMedia>> = if flags & (1u32 << 3) != 0
            {
                Some({
                    __d.enter()?;
                    let value = {
                        let __id = __d.take_u32()?;
                        decode_message_media_profile(profile, __id, __d)?
                    };
                    __d.leave();
                    ::std::boxed::Box::new(value)
                })
            } else {
                None
            };
            let reply_markup: Option<::std::boxed::Box<rtd_tg::ReplyMarkup>> =
                if flags & (1u32 << 4) != 0 {
                    Some({
                        __d.enter()?;
                        let value = {
                            let __id = __d.take_u32()?;
                            decode_reply_markup_profile(profile, __id, __d)?
                        };
                        __d.leave();
                        ::std::boxed::Box::new(value)
                    })
                } else {
                    None
                };
            let reply_to: Option<::std::boxed::Box<rtd_tg::MessageReplyHeader>> =
                if flags & (1u32 << 6) != 0 {
                    Some({
                        __d.enter()?;
                        let value = {
                            let __id = __d.take_u32()?;
                            decode_message_reply_header_profile(profile, __id, __d)?
                        };
                        __d.leave();
                        ::std::boxed::Box::new(value)
                    })
                } else {
                    None
                };
            let rich_message: Option<::std::boxed::Box<rtd_tg::RichMessage>> =
                if flags & (1u32 << 8) != 0 {
                    Some({
                        __d.enter()?;
                        let value = {
                            let __id = __d.take_u32()?;
                            decode_rich_message_profile(profile, __id, __d)?
                        };
                        __d.leave();
                        ::std::boxed::Box::new(value)
                    })
                } else {
                    None
                };
            let chat_instance: Option<i64> = if flags & (1u32 << 10) != 0 {
                Some(__d.take_i64()?)
            } else {
                None
            };
            let anchor_msg_id: Option<i32> = if flags & (1u32 << 11) != 0 {
                Some(__d.take_i32()?)
            } else {
                None
            };
            Ok(rtd_tg::EphemeralMessage {
                flags,
                out,
                welcome_template,
                invert_media,
                noforwards,
                id,
                from_id,
                peer_id,
                receiver_id,
                top_msg_id,
                date,
                message,
                entities,
                media,
                reply_markup,
                reply_to,
                rich_message,
                chat_instance,
                anchor_msg_id,
            })
        }
        RouteMode::Policy => match profile.layer {
            228 => decode_policy_ephemeral_message_228(profile, __d),
            _ => Err(AdmitError::UnsupportedRoute(route)),
        },
        _ => Err(AdmitError::UnsupportedRoute(route)),
    }
}

