pub fn encode_exported_chatlist_invite_profile(
    profile: Profile,
    value: &rtd_tg::ExportedChatlistInvite,
    __w: &mut Writer,
) -> Result<(), ProjectionError> {
    let route = lookup_route_semantic(profile, SemanticId(0xe00371df0adc407f)).ok_or(
        ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0x0c5181ac,
        },
    )?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => {
            __w.put_u32(route.wire_id);
            let rtd_tg::ExportedChatlistInvite {
                flags,
                title,
                url,
                peers,
            } = value;
            let mut __flags_flags = *flags;
            __w.put_u32(__flags_flags);
            __w.put_string(title.as_str());
            __w.put_string(url.as_str());
            __w.put_vector_header(peers.len());
            for item in peers.iter() {
                item.encode(__w);
            }
            Ok(())
        }
        RouteMode::Rewrite => {
            __w.put_u32(route.wire_id);
            let rtd_tg::ExportedChatlistInvite {
                flags,
                title,
                url,
                peers,
            } = value;
            let mut __flags_flags = *flags;
            __w.put_u32(__flags_flags);
            __w.put_string(title.as_str());
            __w.put_string(url.as_str());
            let mut __items: ::std::vec::Vec<::std::vec::Vec<u8>> = ::std::vec::Vec::new();
            for item in peers.iter() {
                let mut __buf = Writer::with_capacity(16);
                match encode_peer_profile(profile, item, &mut __buf) {
                    Ok(()) => __items.push(__buf.into_vec()),
                    Err(ProjectionError::Dropped) => {}
                    Err(error) => return Err(error),
                }
            }
            __w.put_vector_header(__items.len());
            for __item in &__items {
                __w.put_raw(__item);
            }
            Ok(())
        }
        _ => Err(ProjectionError::RouteNotEmitted(route)),
    }
}

