pub fn encode_fact_check_profile(
    profile: Profile,
    value: &rtd_tg::FactCheck,
    __w: &mut Writer,
) -> Result<(), ProjectionError> {
    let route = lookup_route_semantic(profile, SemanticId(0x4f00623b8d02452e)).ok_or(
        ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0xb89bfccf,
        },
    )?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => {
            __w.put_u32(route.wire_id);
            let rtd_tg::FactCheck {
                flags,
                need_check,
                country,
                text,
                hash,
            } = value;
            let mut __flags_flags = *flags & !0x00000003u32;
            if *need_check {
                __flags_flags |= 1u32 << 0;
            }
            if country.is_some() {
                __flags_flags |= 1u32 << 1;
            }
            if text.is_some() {
                __flags_flags |= 1u32 << 1;
            }
            __w.put_u32(__flags_flags);
            if let Some(value) = country {
                __w.put_string(value.as_str());
            }
            if let Some(value) = text {
                value.encode(__w);
            }
            __w.put_i64(*hash);
            Ok(())
        }
        RouteMode::Rewrite => {
            __w.put_u32(route.wire_id);
            let rtd_tg::FactCheck {
                flags,
                need_check,
                country,
                text,
                hash,
            } = value;
            let mut __flags_flags = *flags & !0x00000003u32;
            if *need_check {
                __flags_flags |= 1u32 << 0;
            }
            if country.is_some() {
                __flags_flags |= 1u32 << 1;
            }
            if text.is_some() {
                __flags_flags |= 1u32 << 1;
            }
            __w.put_u32(__flags_flags);
            if let Some(value) = country {
                __w.put_string(value.as_str());
            }
            if let Some(value) = text {
                encode_text_with_entities_profile(profile, value, __w)?;
            }
            __w.put_i64(*hash);
            Ok(())
        }
        _ => Err(ProjectionError::RouteNotEmitted(route)),
    }
}

pub fn decode_fact_check_profile(
    profile: Profile,
    id: u32,
    __d: &mut Decoder<'_>,
) -> Result<rtd_tg::FactCheck, AdmitError> {
    let route =
        lookup_route(profile, id).ok_or(AdmitError::Decode(::rtd_bin::Error::UnexpectedId {
            id,
            expected: 0,
        }))?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => Ok(rtd_tg::FactCheck::decode_with_id(
            __d,
            canonical_wire_id(route.semantic).unwrap_or(id),
        )?),
        RouteMode::Rewrite => {
            let flags = __d.take_u32()?;
            let need_check: bool = flags & (1u32 << 0) != 0;
            let country: Option<::std::string::String> = if flags & (1u32 << 1) != 0 {
                Some(__d.take_string()?.to_owned())
            } else {
                None
            };
            let text: Option<::std::boxed::Box<rtd_tg::TextWithEntities>> =
                if flags & (1u32 << 1) != 0 {
                    Some({
                        __d.enter()?;
                        let value = {
                            let __id = __d.take_u32()?;
                            decode_text_with_entities_profile(profile, __id, __d)?
                        };
                        __d.leave();
                        ::std::boxed::Box::new(value)
                    })
                } else {
                    None
                };
            let hash: i64 = __d.take_i64()?;
            Ok(rtd_tg::FactCheck {
                flags,
                need_check,
                country,
                text,
                hash,
            })
        }
        _ => Err(AdmitError::UnsupportedRoute(route)),
    }
}

