                let icon_emoji_id: Option<i64> = if flags & (1u32 << 0) != 0 {
                    Some(__d.take_i64()?)
                } else {
                    None
                };
                let top_message: i32 = __d.take_i32()?;
                let read_inbox_max_id: i32 = __d.take_i32()?;
                let read_outbox_max_id: i32 = __d.take_i32()?;
                let unread_count: i32 = __d.take_i32()?;
