pub fn encode_input_single_media_profile(
    profile: Profile,
    value: &rtd_tg::InputSingleMedia,
    __w: &mut Writer,
) -> Result<(), ProjectionError> {
    let route = lookup_route_semantic(profile, SemanticId(0x4738bd312dc813c1)).ok_or(
        ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0x1cc6e91f,
        },
    )?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => {
            __w.put_u32(route.wire_id);
            let rtd_tg::InputSingleMedia {
                flags,
                media,
                random_id,
                message,
                entities,
            } = value;
            let mut __flags_flags = *flags & !0x00000001u32;
            if entities.is_some() {
                __flags_flags |= 1u32 << 0;
            }
            __w.put_u32(__flags_flags);
            media.encode(__w);
            __w.put_i64(*random_id);
            __w.put_string(message.as_str());
            if let Some(value) = entities {
                __w.put_vector_header(value.len());
                for item in value.iter() {
                    item.encode(__w);
                }
            }
            Ok(())
        }
        RouteMode::Rewrite => {
            __w.put_u32(route.wire_id);
            let rtd_tg::InputSingleMedia {
                flags,
                media,
                random_id,
                message,
                entities,
            } = value;
            let mut __flags_flags = *flags & !0x00000001u32;
            if entities.is_some() {
                __flags_flags |= 1u32 << 0;
            }
            __w.put_u32(__flags_flags);
            encode_input_media_profile(profile, media, __w)?;
            __w.put_i64(*random_id);
            __w.put_string(message.as_str());
            if let Some(value) = entities {
                let mut __items: ::std::vec::Vec<::std::vec::Vec<u8>> = ::std::vec::Vec::new();
                for item in value.iter() {
                    let mut __buf = Writer::with_capacity(16);
                    match encode_message_entity_profile(profile, item, &mut __buf) {
                        Ok(()) => __items.push(__buf.into_vec()),
                        Err(ProjectionError::Dropped) => {}
                        Err(error) => return Err(error),
                    }
                }
                __w.put_vector_header(__items.len());
                for __item in &__items {
                    __w.put_raw(__item);
                }
            }
            Ok(())
        }
        _ => Err(ProjectionError::RouteNotEmitted(route)),
    }
}

pub fn decode_input_single_media_profile(
    profile: Profile,
    id: u32,
    __d: &mut Decoder<'_>,
) -> Result<rtd_tg::InputSingleMedia, AdmitError> {
    let route =
        lookup_route(profile, id).ok_or(AdmitError::Decode(::rtd_bin::Error::UnexpectedId {
            id,
            expected: 0,
        }))?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => Ok(rtd_tg::InputSingleMedia::decode_with_id(
            __d,
            canonical_wire_id(route.semantic).unwrap_or(id),
        )?),
        RouteMode::Rewrite => {
            let flags = __d.take_u32()?;
            let media: ::std::boxed::Box<rtd_tg::InputMedia> = {
                __d.enter()?;
                let value = {
                    let __id = __d.take_u32()?;
                    decode_input_media_profile(profile, __id, __d)?
                };
                __d.leave();
                ::std::boxed::Box::new(value)
            };
            let random_id: i64 = __d.take_i64()?;
            let message: ::std::string::String = __d.take_string()?.to_owned();
            let entities: Option<::std::vec::Vec<rtd_tg::MessageEntity>> = if flags & (1u32 << 0)
                != 0
            {
                Some({
                    let n = __d.take_vector_header()?;
                    let mut items = ::std::vec::Vec::with_capacity(::rtd_bin::preallocate_len(n));
                    for _ in 0..n {
                        items.push({
                            __d.enter()?;
                            let value = {
                                let __id = __d.take_u32()?;
                                decode_message_entity_profile(profile, __id, __d)?
                            };
                            __d.leave();
                            value
                        });
                    }
                    items
                })
            } else {
                None
            };
            Ok(rtd_tg::InputSingleMedia {
                flags,
                media,
                random_id,
                message,
                entities,
            })
        }
        _ => Err(AdmitError::UnsupportedRoute(route)),
    }
}

