pub fn encode_message_extended_media_profile(
    profile: Profile,
    __value: &rtd_tg::MessageExtendedMedia,
    __w: &mut Writer,
) -> Result<(), ProjectionError> {
    match __value {
        rtd_tg::MessageExtendedMedia::MessageExtendedMedia { media } => {
            let route = lookup_route_semantic(profile, SemanticId(0x57859338f7b90d9d)).ok_or(
                ProjectionError::Unrepresentable {
                    layer: profile.layer,
                    wire_id: 0xee479c64,
                },
            )?;
            match route.mode {
                RouteMode::Direct | RouteMode::Retag => {
                    __w.put_u32(route.wire_id);
                    media.encode(__w);
                    Ok(())
                }
                RouteMode::Rewrite => {
                    __w.put_u32(route.wire_id);
                    encode_message_media_profile(profile, media, __w)?;
                    Ok(())
                }
                _ => Err(ProjectionError::RouteNotEmitted(route)),
            }
        }
        rtd_tg::MessageExtendedMedia::MessageExtendedMediaPreview {
            flags,
            w,
            h,
            thumb,
            video_duration,
        } => {
            let route = lookup_route_semantic(profile, SemanticId(0x2adf6f144ad779ac)).ok_or(
                ProjectionError::Unrepresentable {
                    layer: profile.layer,
                    wire_id: 0xad628cc8,
                },
            )?;
            match route.mode {
                RouteMode::Direct | RouteMode::Retag => {
                    __w.put_u32(route.wire_id);
                    let mut __flags_flags = *flags & !0x00000007u32;
                    if w.is_some() {
                        __flags_flags |= 1u32 << 0;
                    }
                    if h.is_some() {
                        __flags_flags |= 1u32 << 0;
                    }
                    if thumb.is_some() {
                        __flags_flags |= 1u32 << 1;
                    }
                    if video_duration.is_some() {
                        __flags_flags |= 1u32 << 2;
                    }
                    __w.put_u32(__flags_flags);
                    if let Some(value) = w {
                        __w.put_i32(*value);
                    }
                    if let Some(value) = h {
                        __w.put_i32(*value);
                    }
                    if let Some(value) = thumb {
                        value.encode(__w);
                    }
                    if let Some(value) = video_duration {
                        __w.put_i32(*value);
                    }
                    Ok(())
                }
                RouteMode::Rewrite => {
                    __w.put_u32(route.wire_id);
                    let mut __flags_flags = *flags & !0x00000007u32;
                    if w.is_some() {
                        __flags_flags |= 1u32 << 0;
                    }
                    if h.is_some() {
                        __flags_flags |= 1u32 << 0;
                    }
                    if thumb.is_some() {
                        __flags_flags |= 1u32 << 1;
                    }
                    if video_duration.is_some() {
                        __flags_flags |= 1u32 << 2;
                    }
                    __w.put_u32(__flags_flags);
                    if let Some(value) = w {
                        __w.put_i32(*value);
                    }
                    if let Some(value) = h {
                        __w.put_i32(*value);
                    }
                    if let Some(value) = thumb {
                        encode_photo_size_profile(profile, value, __w)?;
                    }
                    if let Some(value) = video_duration {
                        __w.put_i32(*value);
                    }
                    Ok(())
                }
                _ => Err(ProjectionError::RouteNotEmitted(route)),
            }
        }
    }
}

