pub fn decode_message_fwd_header_profile(
    profile: Profile,
    id: u32,
    __d: &mut Decoder<'_>,
) -> Result<rtd_tg::MessageFwdHeader, AdmitError> {
    let route =
        lookup_route(profile, id).ok_or(AdmitError::Decode(::rtd_bin::Error::UnexpectedId {
            id,
            expected: 0,
        }))?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => Ok(rtd_tg::MessageFwdHeader::decode_with_id(
            __d,
            canonical_wire_id(route.semantic).unwrap_or(id),
        )?),
        RouteMode::Rewrite => {
            let flags = __d.take_u32()?;
            let imported: bool = flags & (1u32 << 7) != 0;
            let saved_out: bool = flags & (1u32 << 11) != 0;
            let from_id: Option<::std::boxed::Box<rtd_tg::Peer>> = if flags & (1u32 << 0) != 0 {
                Some({
                    __d.enter()?;
                    let value = {
                        let __id = __d.take_u32()?;
                        decode_peer_profile(profile, __id, __d)?
                    };
                    __d.leave();
                    ::std::boxed::Box::new(value)
                })
            } else {
                None
            };
            let from_name: Option<::std::string::String> = if flags & (1u32 << 5) != 0 {
                Some(__d.take_string()?.to_owned())
            } else {
                None
            };
            let date: i32 = __d.take_i32()?;
            let channel_post: Option<i32> = if flags & (1u32 << 2) != 0 {
                Some(__d.take_i32()?)
            } else {
                None
            };
            let post_author: Option<::std::string::String> = if flags & (1u32 << 3) != 0 {
                Some(__d.take_string()?.to_owned())
            } else {
                None
            };
            let saved_from_peer: Option<::std::boxed::Box<rtd_tg::Peer>> =
                if flags & (1u32 << 4) != 0 {
                    Some({
                        __d.enter()?;
                        let value = {
                            let __id = __d.take_u32()?;
                            decode_peer_profile(profile, __id, __d)?
                        };
                        __d.leave();
                        ::std::boxed::Box::new(value)
                    })
                } else {
                    None
                };
            let saved_from_msg_id: Option<i32> = if flags & (1u32 << 4) != 0 {
                Some(__d.take_i32()?)
            } else {
                None
            };
            let saved_from_id: Option<::std::boxed::Box<rtd_tg::Peer>> = if flags & (1u32 << 8) != 0
            {
                Some({
                    __d.enter()?;
                    let value = {
                        let __id = __d.take_u32()?;
                        decode_peer_profile(profile, __id, __d)?
                    };
                    __d.leave();
                    ::std::boxed::Box::new(value)
                })
            } else {
                None
            };
            let saved_from_name: Option<::std::string::String> = if flags & (1u32 << 9) != 0 {
                Some(__d.take_string()?.to_owned())
            } else {
                None
            };
            let saved_date: Option<i32> = if flags & (1u32 << 10) != 0 {
                Some(__d.take_i32()?)
            } else {
                None
            };
            let psa_type: Option<::std::string::String> = if flags & (1u32 << 6) != 0 {
                Some(__d.take_string()?.to_owned())
            } else {
                None
            };
            Ok(rtd_tg::MessageFwdHeader {
                flags,
                imported,
                saved_out,
                from_id,
                from_name,
                date,
                channel_post,
                post_author,
                saved_from_peer,
                saved_from_msg_id,
                saved_from_id,
                saved_from_name,
                saved_date,
                psa_type,
            })
        }
        _ => Err(AdmitError::UnsupportedRoute(route)),
    }
}

