pub fn decode_messages_filter_profile(
    profile: Profile,
    id: u32,
    __d: &mut Decoder<'_>,
) -> Result<rtd_tg::MessagesFilter, AdmitError> {
    let route =
        lookup_route(profile, id).ok_or(AdmitError::Decode(::rtd_bin::Error::UnexpectedId {
            id,
            expected: 0,
        }))?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => Ok(rtd_tg::MessagesFilter::decode_with_id(
            __d,
            canonical_wire_id(route.semantic).unwrap_or(id),
        )?),
        RouteMode::Rewrite => match route.semantic.0 {
            0x03ebc497967b472b => Ok(rtd_tg::MessagesFilter::InputMessagesFilterChatPhotos),
            0x0d6f5b5fb2828db0 => Ok(rtd_tg::MessagesFilter::InputMessagesFilterContacts),
            0xb69ac3593443ca41 => Ok(rtd_tg::MessagesFilter::InputMessagesFilterDocument),
            0x7e6c9d259b160e25 => Ok(rtd_tg::MessagesFilter::InputMessagesFilterEmpty),
            0xe0b0cb61d5749c2b => Ok(rtd_tg::MessagesFilter::InputMessagesFilterGeo),
            0x99647444d2a02678 => Ok(rtd_tg::MessagesFilter::InputMessagesFilterGif),
            0x9016d1b2c694af65 => Ok(rtd_tg::MessagesFilter::InputMessagesFilterMusic),
            0x111245ab19465f02 => Ok(rtd_tg::MessagesFilter::InputMessagesFilterMyMentions),
            0x780ae5d34a967e63 => {
                let flags = __d.take_u32()?;
                let missed: bool = flags & (1u32 << 0) != 0;
                Ok(rtd_tg::MessagesFilter::InputMessagesFilterPhoneCalls { flags, missed })
            }
            0x90cdb6efc4184090 => Ok(rtd_tg::MessagesFilter::InputMessagesFilterPhotoVideo),
            0x111a088971811e22 => Ok(rtd_tg::MessagesFilter::InputMessagesFilterPhotos),
            0xc7c1a0e007c4e308 => Ok(rtd_tg::MessagesFilter::InputMessagesFilterPinned),
            0x0be59b962bb97a47 => Ok(rtd_tg::MessagesFilter::InputMessagesFilterPoll),
            0xfbe8212acd7aa2ef => Ok(rtd_tg::MessagesFilter::InputMessagesFilterRoundVideo),
            0x909d2bd5af9cd0c3 => Ok(rtd_tg::MessagesFilter::InputMessagesFilterRoundVoice),
            0x4f3d4997096bdfa6 => Ok(rtd_tg::MessagesFilter::InputMessagesFilterUrl),
            0xadd315d5f0473151 => Ok(rtd_tg::MessagesFilter::InputMessagesFilterVideo),
            0xa1b736609a1a8882 => Ok(rtd_tg::MessagesFilter::InputMessagesFilterVoice),
            _ => Err(AdmitError::UnsupportedRoute(route)),
        },
        _ => Err(AdmitError::UnsupportedRoute(route)),
    }
}

