            if cooldown_until_date.is_some() {
                __flags_flags |= 1u32 << 1;
            }
            __w.put_u32(__flags_flags);
            __w.put_i32(*slot);
            if let Some(value) = peer {
                encode_peer_profile(profile, value, __w)?;
            }
