pub fn encode_onramp_availability_profile(
    profile: Profile,
    value: &rtd_tg::OnrampAvailability,
    __w: &mut Writer,
) -> Result<(), ProjectionError> {
    let route = lookup_route_semantic(profile, SemanticId(0x77d98bde803729d1)).ok_or(
        ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0xf9c84973,
        },
    )?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => {
            __w.put_u32(route.wire_id);
            let rtd_tg::OnrampAvailability {
                flags,
                allowed,
                buy_allowed,
                country_code,
                state,
                methods,
            } = value;
            let mut __flags_flags = *flags & !0x00000007u32;
            if *allowed {
                __flags_flags |= 1u32 << 0;
            }
            if *buy_allowed {
                __flags_flags |= 1u32 << 1;
            }
            if state.is_some() {
                __flags_flags |= 1u32 << 2;
            }
            __w.put_u32(__flags_flags);
            __w.put_string(country_code.as_str());
            if let Some(value) = state {
                __w.put_string(value.as_str());
            }
            __w.put_vector_header(methods.len());
            for item in methods.iter() {
                item.encode(__w);
            }
            Ok(())
        }
        RouteMode::Rewrite => {
            __w.put_u32(route.wire_id);
            let rtd_tg::OnrampAvailability {
                flags,
                allowed,
                buy_allowed,
                country_code,
                state,
                methods,
            } = value;
            let mut __flags_flags = *flags & !0x00000007u32;
            if *allowed {
                __flags_flags |= 1u32 << 0;
            }
            if *buy_allowed {
                __flags_flags |= 1u32 << 1;
            }
            if state.is_some() {
                __flags_flags |= 1u32 << 2;
            }
            __w.put_u32(__flags_flags);
            __w.put_string(country_code.as_str());
            if let Some(value) = state {
                __w.put_string(value.as_str());
            }
            let mut __items: ::std::vec::Vec<::std::vec::Vec<u8>> = ::std::vec::Vec::new();
            for item in methods.iter() {
                let mut __buf = Writer::with_capacity(16);
                match encode_onramp_method_availability_profile(profile, item, &mut __buf) {
                    Ok(()) => __items.push(__buf.into_vec()),
                    Err(ProjectionError::Dropped) => {}
                    Err(error) => return Err(error),
                }
            }
            __w.put_vector_header(__items.len());
            for __item in &__items {
                __w.put_raw(__item);
            }
            Ok(())
        }
        _ => Err(ProjectionError::RouteNotEmitted(route)),
    }
}

