pub fn decode_payment_requested_info_profile(
    profile: Profile,
    id: u32,
    __d: &mut Decoder<'_>,
) -> Result<rtd_tg::PaymentRequestedInfo, AdmitError> {
    let route =
        lookup_route(profile, id).ok_or(AdmitError::Decode(::rtd_bin::Error::UnexpectedId {
            id,
            expected: 0,
        }))?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => Ok(rtd_tg::PaymentRequestedInfo::decode_with_id(
            __d,
            canonical_wire_id(route.semantic).unwrap_or(id),
        )?),
        RouteMode::Rewrite => {
            let flags = __d.take_u32()?;
            let name: Option<::std::string::String> = if flags & (1u32 << 0) != 0 {
                Some(__d.take_string()?.to_owned())
            } else {
                None
            };
            let phone: Option<::std::string::String> = if flags & (1u32 << 1) != 0 {
                Some(__d.take_string()?.to_owned())
            } else {
                None
            };
            let email: Option<::std::string::String> = if flags & (1u32 << 2) != 0 {
                Some(__d.take_string()?.to_owned())
            } else {
                None
            };
            let shipping_address: Option<::std::boxed::Box<rtd_tg::PostAddress>> =
                if flags & (1u32 << 3) != 0 {
                    Some({
                        __d.enter()?;
                        let value = {
                            let __id = __d.take_u32()?;
                            decode_post_address_profile(profile, __id, __d)?
                        };
                        __d.leave();
                        ::std::boxed::Box::new(value)
                    })
                } else {
                    None
                };
            Ok(rtd_tg::PaymentRequestedInfo {
                flags,
                name,
                phone,
                email,
                shipping_address,
            })
        }
        _ => Err(AdmitError::UnsupportedRoute(route)),
    }
}

