pub fn decode_privacy_rule_profile(
    profile: Profile,
    id: u32,
    __d: &mut Decoder<'_>,
) -> Result<rtd_tg::PrivacyRule, AdmitError> {
    let route =
        lookup_route(profile, id).ok_or(AdmitError::Decode(::rtd_bin::Error::UnexpectedId {
            id,
            expected: 0,
        }))?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => Ok(rtd_tg::PrivacyRule::decode_with_id(
            __d,
            canonical_wire_id(route.semantic).unwrap_or(id),
        )?),
        RouteMode::Rewrite => match route.semantic.0 {
            0x2bb7dc23b060cb48 => Ok(rtd_tg::PrivacyRule::PrivacyValueAllowAll),
            0x28aa99962dd5e9a7 => Ok(rtd_tg::PrivacyRule::PrivacyValueAllowBots),
            0x6fc92966ddc3e146 => {
                let chats: ::std::vec::Vec<i64> = {
                    let n = __d.take_vector_header()?;
                    let mut items = ::std::vec::Vec::with_capacity(::rtd_bin::preallocate_len(n));
                    for _ in 0..n {
                        items.push(__d.take_i64()?);
                    }
                    items
                };
                Ok(rtd_tg::PrivacyRule::PrivacyValueAllowChatParticipants { chats })
            }
            0x38017de237abbe9b => Ok(rtd_tg::PrivacyRule::PrivacyValueAllowCloseFriends),
            0xe2b509877a8f06f7 => Ok(rtd_tg::PrivacyRule::PrivacyValueAllowContacts),
            0xabcab8b03a17f0c8 => Ok(rtd_tg::PrivacyRule::PrivacyValueAllowPremium),
            0x94f8dd22d2b0b6b5 => {
                let users: ::std::vec::Vec<i64> = {
                    let n = __d.take_vector_header()?;
                    let mut items = ::std::vec::Vec::with_capacity(::rtd_bin::preallocate_len(n));
                    for _ in 0..n {
                        items.push(__d.take_i64()?);
                    }
                    items
                };
                Ok(rtd_tg::PrivacyRule::PrivacyValueAllowUsers { users })
            }
            0xca8c5c75e0ab7c31 => Ok(rtd_tg::PrivacyRule::PrivacyValueDisallowAll),
            0x09f44a125d2a9140 => Ok(rtd_tg::PrivacyRule::PrivacyValueDisallowBots),
            0x0a8e7bc0c192ed33 => {
                let chats: ::std::vec::Vec<i64> = {
                    let n = __d.take_vector_header()?;
                    let mut items = ::std::vec::Vec::with_capacity(::rtd_bin::preallocate_len(n));
                    for _ in 0..n {
                        items.push(__d.take_i64()?);
                    }
                    items
                };
                Ok(rtd_tg::PrivacyRule::PrivacyValueDisallowChatParticipants { chats })
            }
            0x827f93722ee95dc3 => Ok(rtd_tg::PrivacyRule::PrivacyValueDisallowContacts),
            0x6152c6e2698f19f1 => {
                let users: ::std::vec::Vec<i64> = {
                    let n = __d.take_vector_header()?;
                    let mut items = ::std::vec::Vec::with_capacity(::rtd_bin::preallocate_len(n));
                    for _ in 0..n {
                        items.push(__d.take_i64()?);
                    }
                    items
                };
                Ok(rtd_tg::PrivacyRule::PrivacyValueDisallowUsers { users })
            }
            _ => Err(AdmitError::UnsupportedRoute(route)),
        },
        _ => Err(AdmitError::UnsupportedRoute(route)),
    }
}

