pub fn decode_saved_star_gift_profile(
    profile: Profile,
    id: u32,
    __d: &mut Decoder<'_>,
) -> Result<rtd_tg::SavedStarGift, AdmitError> {
    let route =
        lookup_route(profile, id).ok_or(AdmitError::Decode(::rtd_bin::Error::UnexpectedId {
            id,
            expected: 0,
        }))?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => Ok(rtd_tg::SavedStarGift::decode_with_id(
            __d,
            canonical_wire_id(route.semantic).unwrap_or(id),
        )?),
        RouteMode::Rewrite => {
            let flags = __d.take_u32()?;
            let name_hidden: bool = flags & (1u32 << 0) != 0;
            let unsaved: bool = flags & (1u32 << 5) != 0;
            let refunded: bool = flags & (1u32 << 9) != 0;
            let can_upgrade: bool = flags & (1u32 << 10) != 0;
            let pinned_to_top: bool = flags & (1u32 << 12) != 0;
            let upgrade_separate: bool = flags & (1u32 << 17) != 0;
            let from_id: Option<::std::boxed::Box<rtd_tg::Peer>> = if flags & (1u32 << 1) != 0 {
                Some({
                    __d.enter()?;
                    let value = {
                        let __id = __d.take_u32()?;
                        decode_peer_profile(profile, __id, __d)?
                    };
                    __d.leave();
                    ::std::boxed::Box::new(value)
                })
            } else {
                None
            };
            let date: i32 = __d.take_i32()?;
            let gift: ::std::boxed::Box<rtd_tg::StarGift> = {
                __d.enter()?;
                let value = {
                    let __id = __d.take_u32()?;
                    decode_star_gift_profile(profile, __id, __d)?
                };
                __d.leave();
                ::std::boxed::Box::new(value)
            };
            let message: Option<::std::boxed::Box<rtd_tg::TextWithEntities>> =
                if flags & (1u32 << 2) != 0 {
                    Some({
                        __d.enter()?;
                        let value = {
                            let __id = __d.take_u32()?;
                            decode_text_with_entities_profile(profile, __id, __d)?
                        };
                        __d.leave();
                        ::std::boxed::Box::new(value)
                    })
                } else {
                    None
                };
            let msg_id: Option<i32> = if flags & (1u32 << 3) != 0 {
                Some(__d.take_i32()?)
            } else {
                None
            };
            let saved_id: Option<i64> = if flags & (1u32 << 11) != 0 {
                Some(__d.take_i64()?)
            } else {
                None
            };
            let convert_stars: Option<i64> = if flags & (1u32 << 4) != 0 {
                Some(__d.take_i64()?)
            } else {
                None
            };
            let upgrade_stars: Option<i64> = if flags & (1u32 << 6) != 0 {
                Some(__d.take_i64()?)
            } else {
                None
            };
            let can_export_at: Option<i32> = if flags & (1u32 << 7) != 0 {
                Some(__d.take_i32()?)
            } else {
                None
            };
            let transfer_stars: Option<i64> = if flags & (1u32 << 8) != 0 {
                Some(__d.take_i64()?)
            } else {
                None
            };
            let can_transfer_at: Option<i32> = if flags & (1u32 << 13) != 0 {
                Some(__d.take_i32()?)
            } else {
                None
            };
            let can_resell_at: Option<i32> = if flags & (1u32 << 14) != 0 {
                Some(__d.take_i32()?)
            } else {
                None
            };
            let collection_id: Option<::std::vec::Vec<i32>> = if flags & (1u32 << 15) != 0 {
                Some({
                    let n = __d.take_vector_header()?;
                    let mut items = ::std::vec::Vec::with_capacity(::rtd_bin::preallocate_len(n));
                    for _ in 0..n {
                        items.push(__d.take_i32()?);
                    }
                    items
                })
            } else {
                None
            };
            let prepaid_upgrade_hash: Option<::std::string::String> = if flags & (1u32 << 16) != 0 {
                Some(__d.take_string()?.to_owned())
            } else {
                None
            };
            let drop_original_details_stars: Option<i64> = if flags & (1u32 << 18) != 0 {
                Some(__d.take_i64()?)
            } else {
                None
            };
            let gift_num: Option<i32> = if flags & (1u32 << 19) != 0 {
                Some(__d.take_i32()?)
            } else {
                None
            };
            let can_craft_at: Option<i32> = if flags & (1u32 << 20) != 0 {
                Some(__d.take_i32()?)
            } else {
                None
            };
            Ok(rtd_tg::SavedStarGift {
                flags,
                name_hidden,
                unsaved,
                refunded,
                can_upgrade,
                pinned_to_top,
                upgrade_separate,
                from_id,
                date,
                gift,
                message,
                msg_id,
                saved_id,
                convert_stars,
                upgrade_stars,
                can_export_at,
                transfer_stars,
                can_transfer_at,
                can_resell_at,
                collection_id,
                prepaid_upgrade_hash,
                drop_original_details_stars,
                gift_num,
                can_craft_at,
            })
        }
        _ => Err(AdmitError::UnsupportedRoute(route)),
    }
}

