pub fn decode_secure_value_type_profile(
    profile: Profile,
    id: u32,
    __d: &mut Decoder<'_>,
) -> Result<rtd_tg::SecureValueType, AdmitError> {
    let route =
        lookup_route(profile, id).ok_or(AdmitError::Decode(::rtd_bin::Error::UnexpectedId {
            id,
            expected: 0,
        }))?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => Ok(rtd_tg::SecureValueType::decode_with_id(
            __d,
            canonical_wire_id(route.semantic).unwrap_or(id),
        )?),
        RouteMode::Rewrite => match route.semantic.0 {
            0x1dab1e8a23561e34 => Ok(rtd_tg::SecureValueType::SecureValueTypeAddress),
            0x0cc74c0386b6d65b => Ok(rtd_tg::SecureValueType::SecureValueTypeBankStatement),
            0x93693ba5ff1fd491 => Ok(rtd_tg::SecureValueType::SecureValueTypeDriverLicense),
            0xdd20e8146ecf9a1c => Ok(rtd_tg::SecureValueType::SecureValueTypeEmail),
            0x9718e1e3dda263ba => Ok(rtd_tg::SecureValueType::SecureValueTypeIdentityCard),
            0x5e2d8581647fd74b => Ok(rtd_tg::SecureValueType::SecureValueTypeInternalPassport),
            0xef4744a79669420b => Ok(rtd_tg::SecureValueType::SecureValueTypePassport),
            0xa3dbab3766b55c0a => Ok(rtd_tg::SecureValueType::SecureValueTypePassportRegistration),
            0x6b6880e98ad81e21 => Ok(rtd_tg::SecureValueType::SecureValueTypePersonalDetails),
            0xab5b3d842b01058b => Ok(rtd_tg::SecureValueType::SecureValueTypePhone),
            0x59badb47d68033b2 => Ok(rtd_tg::SecureValueType::SecureValueTypeRentalAgreement),
            0x273d9baea7bd5f12 => Ok(rtd_tg::SecureValueType::SecureValueTypeTemporaryRegistration),
            0x601baee435f655af => Ok(rtd_tg::SecureValueType::SecureValueTypeUtilityBill),
            _ => Err(AdmitError::UnsupportedRoute(route)),
        },
        _ => Err(AdmitError::UnsupportedRoute(route)),
    }
}

pub fn encode_send_as_peer_profile(
    profile: Profile,
    value: &rtd_tg::SendAsPeer,
    __w: &mut Writer,
) -> Result<(), ProjectionError> {
    let route = lookup_route_semantic(profile, SemanticId(0x6d2d25e79a38dc13)).ok_or(
        ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0xb81c7034,
        },
    )?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => {
            __w.put_u32(route.wire_id);
            let rtd_tg::SendAsPeer {
                flags,
                premium_required,
                peer,
            } = value;
            let mut __flags_flags = *flags & !0x00000001u32;
            if *premium_required {
                __flags_flags |= 1u32 << 0;
            }
            __w.put_u32(__flags_flags);
            peer.encode(__w);
            Ok(())
        }
        RouteMode::Rewrite => {
            __w.put_u32(route.wire_id);
            let rtd_tg::SendAsPeer {
                flags,
                premium_required,
                peer,
            } = value;
            let mut __flags_flags = *flags & !0x00000001u32;
            if *premium_required {
                __flags_flags |= 1u32 << 0;
            }
            __w.put_u32(__flags_flags);
            encode_peer_profile(profile, peer, __w)?;
            Ok(())
        }
        _ => Err(ProjectionError::RouteNotEmitted(route)),
    }
}

pub fn decode_send_as_peer_profile(
    profile: Profile,
    id: u32,
    __d: &mut Decoder<'_>,
) -> Result<rtd_tg::SendAsPeer, AdmitError> {
    let route =
        lookup_route(profile, id).ok_or(AdmitError::Decode(::rtd_bin::Error::UnexpectedId {
            id,
            expected: 0,
        }))?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => Ok(rtd_tg::SendAsPeer::decode_with_id(
            __d,
            canonical_wire_id(route.semantic).unwrap_or(id),
        )?),
        RouteMode::Rewrite => {
            let flags = __d.take_u32()?;
            let premium_required: bool = flags & (1u32 << 0) != 0;
            let peer: ::std::boxed::Box<rtd_tg::Peer> = {
                __d.enter()?;
                let value = {
                    let __id = __d.take_u32()?;
                    decode_peer_profile(profile, __id, __d)?
                };
                __d.leave();
                ::std::boxed::Box::new(value)
            };
            Ok(rtd_tg::SendAsPeer {
                flags,
                premium_required,
                peer,
            })
        }
        _ => Err(AdmitError::UnsupportedRoute(route)),
    }
}

