pub fn encode_share_theme_profile(
    profile: Profile,
    __value: &rtd_tg::ShareTheme,
    __w: &mut Writer,
) -> Result<(), ProjectionError> {
    match __value {
        rtd_tg::ShareTheme::InputShareThemeGift { stargift } => {
            let route = lookup_route_semantic(profile, SemanticId(0x621c9ee12dc6ccb4)).ok_or(
                ProjectionError::Unrepresentable {
                    layer: profile.layer,
                    wire_id: 0x3fb92b5b,
                },
            )?;
            match route.mode {
                RouteMode::Direct | RouteMode::Retag => {
                    __w.put_u32(route.wire_id);
                    stargift.encode(__w);
                    Ok(())
                }
                RouteMode::Rewrite => {
                    __w.put_u32(route.wire_id);
                    encode_input_saved_star_gift_profile(profile, stargift, __w)?;
                    Ok(())
                }
                _ => Err(ProjectionError::RouteNotEmitted(route)),
            }
        }
        rtd_tg::ShareTheme::ShareThemeDefault => {
            let route = lookup_route_semantic(profile, SemanticId(0xa928c34af1032dd1)).ok_or(
                ProjectionError::Unrepresentable {
                    layer: profile.layer,
                    wire_id: 0x95ace84f,
                },
            )?;
            match route.mode {
                RouteMode::Direct | RouteMode::Retag => {
                    __w.put_u32(route.wire_id);
                    Ok(())
                }
                RouteMode::Rewrite => {
                    __w.put_u32(route.wire_id);
                    Ok(())
                }
                _ => Err(ProjectionError::RouteNotEmitted(route)),
            }
        }
        rtd_tg::ShareTheme::ShareThemeEmojiBackdrop {
            flags,
            backdrop_id,
            emojis,
        } => {
            let route = lookup_route_semantic(profile, SemanticId(0x65aa30a099ada51d)).ok_or(
                ProjectionError::Unrepresentable {
                    layer: profile.layer,
                    wire_id: 0x64b334e1,
                },
            )?;
            match route.mode {
                RouteMode::Direct | RouteMode::Retag => {
                    __w.put_u32(route.wire_id);
                    let mut __flags_flags = *flags & !0x00000003u32;
                    if backdrop_id.is_some() {
                        __flags_flags |= 1u32 << 0;
                    }
                    if emojis.is_some() {
                        __flags_flags |= 1u32 << 1;
                    }
                    __w.put_u32(__flags_flags);
                    if let Some(value) = backdrop_id {
                        __w.put_i32(*value);
                    }
                    if let Some(value) = emojis {
                        __w.put_vector_header(value.len());
                        for item in value.iter() {
                            item.encode(__w);
                        }
                    }
                    Ok(())
                }
                RouteMode::Rewrite => {
                    __w.put_u32(route.wire_id);
                    let mut __flags_flags = *flags & !0x00000003u32;
                    if backdrop_id.is_some() {
                        __flags_flags |= 1u32 << 0;
                    }
                    if emojis.is_some() {
                        __flags_flags |= 1u32 << 1;
                    }
                    __w.put_u32(__flags_flags);
                    if let Some(value) = backdrop_id {
                        __w.put_i32(*value);
                    }
                    if let Some(value) = emojis {
                        let mut __items: ::std::vec::Vec<::std::vec::Vec<u8>> =
                            ::std::vec::Vec::new();
                        for item in value.iter() {
                            let mut __buf = Writer::with_capacity(16);
                            match encode_reaction_profile(profile, item, &mut __buf) {
                                Ok(()) => __items.push(__buf.into_vec()),
                                Err(ProjectionError::Dropped) => {}
                                Err(error) => return Err(error),
                            }
                        }
                        __w.put_vector_header(__items.len());
                        for __item in &__items {
                            __w.put_raw(__item);
                        }
                    }
                    Ok(())
                }
                _ => Err(ProjectionError::RouteNotEmitted(route)),
            }
        }
        rtd_tg::ShareTheme::ShareThemeGift { stargift } => {
            let route = lookup_route_semantic(profile, SemanticId(0xdbeda6e5408f2717)).ok_or(
                ProjectionError::Unrepresentable {
                    layer: profile.layer,
                    wire_id: 0xebece66d,
                },
            )?;
            match route.mode {
                RouteMode::Direct | RouteMode::Retag => {
                    __w.put_u32(route.wire_id);
                    stargift.encode(__w);
                    Ok(())
                }
                RouteMode::Rewrite => {
                    __w.put_u32(route.wire_id);
                    encode_star_gift_profile(profile, stargift, __w)?;
                    Ok(())
                }
                _ => Err(ProjectionError::RouteNotEmitted(route)),
            }
        }
    }
}

pub fn decode_share_theme_profile(
    profile: Profile,
    id: u32,
    __d: &mut Decoder<'_>,
) -> Result<rtd_tg::ShareTheme, AdmitError> {
    let route =
        lookup_route(profile, id).ok_or(AdmitError::Decode(::rtd_bin::Error::UnexpectedId {
            id,
            expected: 0,
        }))?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => Ok(rtd_tg::ShareTheme::decode_with_id(
            __d,
            canonical_wire_id(route.semantic).unwrap_or(id),
        )?),
        RouteMode::Rewrite => match route.semantic.0 {
            0x621c9ee12dc6ccb4 => {
                let stargift: ::std::boxed::Box<rtd_tg::InputSavedStarGift> = {
                    __d.enter()?;
                    let value = {
                        let __id = __d.take_u32()?;
                        decode_input_saved_star_gift_profile(profile, __id, __d)?
                    };
                    __d.leave();
                    ::std::boxed::Box::new(value)
                };
                Ok(rtd_tg::ShareTheme::InputShareThemeGift { stargift })
            }
            0xa928c34af1032dd1 => Ok(rtd_tg::ShareTheme::ShareThemeDefault),
            0x65aa30a099ada51d => {
                let flags = __d.take_u32()?;
                let backdrop_id: Option<i32> = if flags & (1u32 << 0) != 0 {
                    Some(__d.take_i32()?)
                } else {
                    None
                };
                let emojis: Option<::std::vec::Vec<rtd_tg::Reaction>> = if flags & (1u32 << 1) != 0
                {
                    Some({
                        let n = __d.take_vector_header()?;
                        let mut items =
                            ::std::vec::Vec::with_capacity(::rtd_bin::preallocate_len(n));
                        for _ in 0..n {
                            items.push({
                                __d.enter()?;
                                let value = {
                                    let __id = __d.take_u32()?;
                                    decode_reaction_profile(profile, __id, __d)?
                                };
                                __d.leave();
                                value
                            });
                        }
                        items
                    })
                } else {
                    None
                };
                Ok(rtd_tg::ShareTheme::ShareThemeEmojiBackdrop {
                    flags,
                    backdrop_id,
                    emojis,
                })
            }
            0xdbeda6e5408f2717 => {
                let stargift: ::std::boxed::Box<rtd_tg::StarGift> = {
                    __d.enter()?;
                    let value = {
                        let __id = __d.take_u32()?;
                        decode_star_gift_profile(profile, __id, __d)?
                    };
                    __d.leave();
                    ::std::boxed::Box::new(value)
                };
                Ok(rtd_tg::ShareTheme::ShareThemeGift { stargift })
            }
            _ => Err(AdmitError::UnsupportedRoute(route)),
        },
        _ => Err(AdmitError::UnsupportedRoute(route)),
    }
}

