pub fn decode_sponsored_message_profile(
    profile: Profile,
    id: u32,
    __d: &mut Decoder<'_>,
) -> Result<rtd_tg::SponsoredMessage, AdmitError> {
    let route =
        lookup_route(profile, id).ok_or(AdmitError::Decode(::rtd_bin::Error::UnexpectedId {
            id,
            expected: 0,
        }))?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => Ok(rtd_tg::SponsoredMessage::decode_with_id(
            __d,
            canonical_wire_id(route.semantic).unwrap_or(id),
        )?),
        RouteMode::Rewrite => {
            let flags = __d.take_u32()?;
            let recommended: bool = flags & (1u32 << 5) != 0;
            let can_report: bool = flags & (1u32 << 12) != 0;
            let random_id: ::std::vec::Vec<u8> = __d.take_bytes()?.to_vec();
            let url: ::std::string::String = __d.take_string()?.to_owned();
            let title: ::std::string::String = __d.take_string()?.to_owned();
            let message: ::std::string::String = __d.take_string()?.to_owned();
            let entities: Option<::std::vec::Vec<rtd_tg::MessageEntity>> = if flags & (1u32 << 1)
                != 0
            {
                Some({
                    let n = __d.take_vector_header()?;
                    let mut items = ::std::vec::Vec::with_capacity(::rtd_bin::preallocate_len(n));
                    for _ in 0..n {
                        items.push({
                            __d.enter()?;
                            let value = {
                                let __id = __d.take_u32()?;
                                decode_message_entity_profile(profile, __id, __d)?
                            };
                            __d.leave();
                            value
                        });
                    }
                    items
                })
            } else {
                None
            };
            let photo: Option<::std::boxed::Box<rtd_tg::Photo>> = if flags & (1u32 << 6) != 0 {
                Some({
                    __d.enter()?;
                    let value = {
                        let __id = __d.take_u32()?;
                        decode_photo_profile(profile, __id, __d)?
                    };
                    __d.leave();
                    ::std::boxed::Box::new(value)
                })
            } else {
                None
            };
            let media: Option<::std::boxed::Box<rtd_tg::MessageMedia>> =
                if flags & (1u32 << 14) != 0 {
                    Some({
                        __d.enter()?;
                        let value = {
                            let __id = __d.take_u32()?;
                            decode_message_media_profile(profile, __id, __d)?
                        };
                        __d.leave();
                        ::std::boxed::Box::new(value)
                    })
                } else {
                    None
                };
            let color: Option<::std::boxed::Box<rtd_tg::PeerColor>> = if flags & (1u32 << 13) != 0 {
                Some({
                    __d.enter()?;
                    let value = {
                        let __id = __d.take_u32()?;
                        decode_peer_color_profile(profile, __id, __d)?
                    };
                    __d.leave();
                    ::std::boxed::Box::new(value)
                })
            } else {
                None
            };
            let button_text: ::std::string::String = __d.take_string()?.to_owned();
            let sponsor_info: Option<::std::string::String> = if flags & (1u32 << 7) != 0 {
                Some(__d.take_string()?.to_owned())
            } else {
                None
            };
            let additional_info: Option<::std::string::String> = if flags & (1u32 << 8) != 0 {
                Some(__d.take_string()?.to_owned())
            } else {
                None
            };
            let min_display_duration: Option<i32> = if flags & (1u32 << 15) != 0 {
                Some(__d.take_i32()?)
            } else {
                None
            };
            let max_display_duration: Option<i32> = if flags & (1u32 << 15) != 0 {
                Some(__d.take_i32()?)
            } else {
                None
            };
            Ok(rtd_tg::SponsoredMessage {
                flags,
                recommended,
                can_report,
                random_id,
                url,
                title,
                message,
                entities,
                photo,
                media,
                color,
                button_text,
                sponsor_info,
                additional_info,
                min_display_duration,
                max_display_duration,
            })
        }
        _ => Err(AdmitError::UnsupportedRoute(route)),
    }
}

