pub fn encode_star_gift_active_auction_state_profile(
    profile: Profile,
    value: &rtd_tg::StarGiftActiveAuctionState,
    __w: &mut Writer,
) -> Result<(), ProjectionError> {
    let route = lookup_route_semantic(profile, SemanticId(0xf9240003379abb08)).ok_or(
        ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0xd31bc45d,
        },
    )?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => {
            __w.put_u32(route.wire_id);
            let rtd_tg::StarGiftActiveAuctionState {
                gift,
                state,
                user_state,
            } = value;
            gift.encode(__w);
            state.encode(__w);
            user_state.encode(__w);
            Ok(())
        }
        RouteMode::Rewrite => {
            __w.put_u32(route.wire_id);
            let rtd_tg::StarGiftActiveAuctionState {
                gift,
                state,
                user_state,
            } = value;
            encode_star_gift_profile(profile, gift, __w)?;
            encode_star_gift_auction_state_profile(profile, state, __w)?;
            encode_star_gift_auction_user_state_profile(profile, user_state, __w)?;
            Ok(())
        }
        _ => Err(ProjectionError::RouteNotEmitted(route)),
    }
}

