pub fn encode_todo_list_profile(
    profile: Profile,
    value: &rtd_tg::TodoList,
    __w: &mut Writer,
) -> Result<(), ProjectionError> {
    let route = lookup_route_semantic(profile, SemanticId(0x812449768285d248)).ok_or(
        ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0x49b92a26,
        },
    )?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => {
            __w.put_u32(route.wire_id);
            let rtd_tg::TodoList {
                flags,
                others_can_append,
                others_can_complete,
                title,
                list,
            } = value;
            let mut __flags_flags = *flags & !0x00000003u32;
            if *others_can_append {
                __flags_flags |= 1u32 << 0;
            }
            if *others_can_complete {
                __flags_flags |= 1u32 << 1;
            }
            __w.put_u32(__flags_flags);
            title.encode(__w);
            __w.put_vector_header(list.len());
            for item in list.iter() {
                item.encode(__w);
            }
            Ok(())
        }
        RouteMode::Rewrite => {
            __w.put_u32(route.wire_id);
            let rtd_tg::TodoList {
                flags,
                others_can_append,
                others_can_complete,
                title,
                list,
            } = value;
            let mut __flags_flags = *flags & !0x00000003u32;
            if *others_can_append {
                __flags_flags |= 1u32 << 0;
            }
            if *others_can_complete {
                __flags_flags |= 1u32 << 1;
            }
            __w.put_u32(__flags_flags);
            encode_text_with_entities_profile(profile, title, __w)?;
            let mut __items: ::std::vec::Vec<::std::vec::Vec<u8>> = ::std::vec::Vec::new();
            for item in list.iter() {
                let mut __buf = Writer::with_capacity(16);
                match encode_todo_item_profile(profile, item, &mut __buf) {
                    Ok(()) => __items.push(__buf.into_vec()),
                    Err(ProjectionError::Dropped) => {}
                    Err(error) => return Err(error),
                }
            }
            __w.put_vector_header(__items.len());
            for __item in &__items {
                __w.put_raw(__item);
            }
            Ok(())
        }
        _ => Err(ProjectionError::RouteNotEmitted(route)),
    }
}

pub fn decode_todo_list_profile(
    profile: Profile,
    id: u32,
    __d: &mut Decoder<'_>,
) -> Result<rtd_tg::TodoList, AdmitError> {
    let route =
        lookup_route(profile, id).ok_or(AdmitError::Decode(::rtd_bin::Error::UnexpectedId {
            id,
            expected: 0,
        }))?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => Ok(rtd_tg::TodoList::decode_with_id(
            __d,
            canonical_wire_id(route.semantic).unwrap_or(id),
        )?),
        RouteMode::Rewrite => {
            let flags = __d.take_u32()?;
            let others_can_append: bool = flags & (1u32 << 0) != 0;
            let others_can_complete: bool = flags & (1u32 << 1) != 0;
            let title: ::std::boxed::Box<rtd_tg::TextWithEntities> = {
                __d.enter()?;
                let value = {
                    let __id = __d.take_u32()?;
                    decode_text_with_entities_profile(profile, __id, __d)?
                };
                __d.leave();
                ::std::boxed::Box::new(value)
            };
            let list: ::std::vec::Vec<rtd_tg::TodoItem> = {
                let n = __d.take_vector_header()?;
                let mut items = ::std::vec::Vec::with_capacity(::rtd_bin::preallocate_len(n));
                for _ in 0..n {
                    items.push({
                        __d.enter()?;
                        let value = {
                            let __id = __d.take_u32()?;
                            decode_todo_item_profile(profile, __id, __d)?
                        };
                        __d.leave();
                        value
                    });
                }
                items
            };
            Ok(rtd_tg::TodoList {
                flags,
                others_can_append,
                others_can_complete,
                title,
                list,
            })
        }
        _ => Err(AdmitError::UnsupportedRoute(route)),
    }
}

