pub fn decode_top_peer_category_profile(
    profile: Profile,
    id: u32,
    __d: &mut Decoder<'_>,
) -> Result<rtd_tg::TopPeerCategory, AdmitError> {
    let route =
        lookup_route(profile, id).ok_or(AdmitError::Decode(::rtd_bin::Error::UnexpectedId {
            id,
            expected: 0,
        }))?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => Ok(rtd_tg::TopPeerCategory::decode_with_id(
            __d,
            canonical_wire_id(route.semantic).unwrap_or(id),
        )?),
        RouteMode::Rewrite => match route.semantic.0 {
            0x871fac321a26dbc7 => Ok(rtd_tg::TopPeerCategory::TopPeerCategoryBotsApp),
            0x685792ec0f6a18cc => Ok(rtd_tg::TopPeerCategory::TopPeerCategoryBotsGuestChat),
            0x132b50edb28d9c4a => Ok(rtd_tg::TopPeerCategory::TopPeerCategoryBotsInline),
            0x16ab20be4cadde71 => Ok(rtd_tg::TopPeerCategory::TopPeerCategoryBotsPM),
            0xad37a1571e205ca4 => Ok(rtd_tg::TopPeerCategory::TopPeerCategoryChannels),
            0xcad2a1f99cf06d37 => Ok(rtd_tg::TopPeerCategory::TopPeerCategoryCorrespondents),
            0xc29418e4fc157a59 => Ok(rtd_tg::TopPeerCategory::TopPeerCategoryForwardChats),
            0x58aee03a584fd6d3 => Ok(rtd_tg::TopPeerCategory::TopPeerCategoryForwardUsers),
            0x19930d28475535fb => Ok(rtd_tg::TopPeerCategory::TopPeerCategoryGroups),
            0x2b10448ba82ce8a3 => Ok(rtd_tg::TopPeerCategory::TopPeerCategoryPhoneCalls),
            _ => Err(AdmitError::UnsupportedRoute(route)),
        },
        _ => Err(AdmitError::UnsupportedRoute(route)),
    }
}

pub fn encode_top_peer_category_peers_profile(
    profile: Profile,
    value: &rtd_tg::TopPeerCategoryPeers,
    __w: &mut Writer,
) -> Result<(), ProjectionError> {
    let route = lookup_route_semantic(profile, SemanticId(0xc7584644c6a855f8)).ok_or(
        ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0xfb834291,
        },
    )?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => {
            __w.put_u32(route.wire_id);
            let rtd_tg::TopPeerCategoryPeers {
                category,
                count,
                peers,
            } = value;
            category.encode(__w);
            __w.put_i32(*count);
            __w.put_vector_header(peers.len());
            for item in peers.iter() {
                item.encode(__w);
            }
            Ok(())
        }
        RouteMode::Rewrite => {
            __w.put_u32(route.wire_id);
            let rtd_tg::TopPeerCategoryPeers {
                category,
                count,
                peers,
            } = value;
            encode_top_peer_category_profile(profile, category, __w)?;
            __w.put_i32(*count);
            let mut __items: ::std::vec::Vec<::std::vec::Vec<u8>> = ::std::vec::Vec::new();
            for item in peers.iter() {
                let mut __buf = Writer::with_capacity(16);
                match encode_top_peer_profile(profile, item, &mut __buf) {
                    Ok(()) => __items.push(__buf.into_vec()),
                    Err(ProjectionError::Dropped) => {}
                    Err(error) => return Err(error),
                }
            }
            __w.put_vector_header(__items.len());
            for __item in &__items {
                __w.put_raw(__item);
            }
            Ok(())
        }
        _ => Err(ProjectionError::RouteNotEmitted(route)),
    }
}

pub fn decode_top_peer_category_peers_profile(
    profile: Profile,
    id: u32,
    __d: &mut Decoder<'_>,
) -> Result<rtd_tg::TopPeerCategoryPeers, AdmitError> {
    let route =
        lookup_route(profile, id).ok_or(AdmitError::Decode(::rtd_bin::Error::UnexpectedId {
            id,
            expected: 0,
        }))?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => Ok(rtd_tg::TopPeerCategoryPeers::decode_with_id(
            __d,
            canonical_wire_id(route.semantic).unwrap_or(id),
        )?),
        RouteMode::Rewrite => {
            let category: ::std::boxed::Box<rtd_tg::TopPeerCategory> = {
                __d.enter()?;
                let value = {
                    let __id = __d.take_u32()?;
                    decode_top_peer_category_profile(profile, __id, __d)?
                };
                __d.leave();
                ::std::boxed::Box::new(value)
            };
            let count: i32 = __d.take_i32()?;
            let peers: ::std::vec::Vec<rtd_tg::TopPeer> = {
                let n = __d.take_vector_header()?;
                let mut items = ::std::vec::Vec::with_capacity(::rtd_bin::preallocate_len(n));
                for _ in 0..n {
                    items.push({
                        __d.enter()?;
                        let value = {
                            let __id = __d.take_u32()?;
                            decode_top_peer_profile(profile, __id, __d)?
                        };
                        __d.leave();
                        value
                    });
                }
                items
            };
            Ok(rtd_tg::TopPeerCategoryPeers {
                category,
                count,
                peers,
            })
        }
        _ => Err(AdmitError::UnsupportedRoute(route)),
    }
}

