pub fn encode_wallet_transaction_profile(
    profile: Profile,
    value: &rtd_tg::WalletTransaction,
    __w: &mut Writer,
) -> Result<(), ProjectionError> {
    let route = lookup_route_semantic(profile, SemanticId(0xad740c8c51d6a41e)).ok_or(
        ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0x952dc143,
        },
    )?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => {
            __w.put_u32(route.wire_id);
            let rtd_tg::WalletTransaction {
                flags,
                incoming,
                gasless,
                failed,
                key_change,
                comment_encrypted,
                id,
                amount,
                fee,
                date,
                peer,
                comment,
                tx_hash,
                nft,
            } = value;
            let mut __flags_flags = *flags & !0x000000ffu32;
            if *incoming {
                __flags_flags |= 1u32 << 0;
            }
            if *gasless {
                __flags_flags |= 1u32 << 1;
            }
            if *failed {
                __flags_flags |= 1u32 << 2;
            }
            if *key_change {
                __flags_flags |= 1u32 << 5;
            }
            if *comment_encrypted {
                __flags_flags |= 1u32 << 6;
            }
            if comment.is_some() {
                __flags_flags |= 1u32 << 3;
            }
            if tx_hash.is_some() {
                __flags_flags |= 1u32 << 4;
            }
            if nft.is_some() {
                __flags_flags |= 1u32 << 7;
            }
            __w.put_u32(__flags_flags);
            __w.put_string(id.as_str());
            __w.put_i64(*amount);
            __w.put_i64(*fee);
            __w.put_i32(*date);
            peer.encode(__w);
            if let Some(value) = comment {
                __w.put_string(value.as_str());
            }
            if let Some(value) = tx_hash {
                __w.put_string(value.as_str());
            }
            if let Some(value) = nft {
                value.encode(__w);
            }
            Ok(())
        }
        RouteMode::Rewrite => {
            __w.put_u32(route.wire_id);
            let rtd_tg::WalletTransaction {
                flags,
                incoming,
                gasless,
                failed,
                key_change,
                comment_encrypted,
                id,
                amount,
                fee,
                date,
                peer,
                comment,
                tx_hash,
                nft,
            } = value;
            let mut __flags_flags = *flags & !0x000000ffu32;
            if *incoming {
                __flags_flags |= 1u32 << 0;
            }
            if *gasless {
                __flags_flags |= 1u32 << 1;
            }
            if *failed {
                __flags_flags |= 1u32 << 2;
            }
            if *key_change {
                __flags_flags |= 1u32 << 5;
            }
            if *comment_encrypted {
                __flags_flags |= 1u32 << 6;
            }
            if comment.is_some() {
                __flags_flags |= 1u32 << 3;
            }
            if tx_hash.is_some() {
                __flags_flags |= 1u32 << 4;
            }
            if nft.is_some() {
                __flags_flags |= 1u32 << 7;
            }
            __w.put_u32(__flags_flags);
            __w.put_string(id.as_str());
            __w.put_i64(*amount);
            __w.put_i64(*fee);
            __w.put_i32(*date);
            encode_wallet_transaction_peer_profile(profile, peer, __w)?;
            if let Some(value) = comment {
                __w.put_string(value.as_str());
            }
            if let Some(value) = tx_hash {
                __w.put_string(value.as_str());
            }
            if let Some(value) = nft {
                encode_wallet_nft_item_profile(profile, value, __w)?;
            }
            Ok(())
        }
        _ => Err(ProjectionError::RouteNotEmitted(route)),
    }
}

pub fn decode_wallet_transaction_profile(
    profile: Profile,
    id: u32,
    __d: &mut Decoder<'_>,
) -> Result<rtd_tg::WalletTransaction, AdmitError> {
    let route =
        lookup_route(profile, id).ok_or(AdmitError::Decode(::rtd_bin::Error::UnexpectedId {
            id,
            expected: 0,
        }))?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => Ok(rtd_tg::WalletTransaction::decode_with_id(
            __d,
            canonical_wire_id(route.semantic).unwrap_or(id),
        )?),
        RouteMode::Rewrite => {
            let flags = __d.take_u32()?;
            let incoming: bool = flags & (1u32 << 0) != 0;
            let gasless: bool = flags & (1u32 << 1) != 0;
            let failed: bool = flags & (1u32 << 2) != 0;
            let key_change: bool = flags & (1u32 << 5) != 0;
            let comment_encrypted: bool = flags & (1u32 << 6) != 0;
            let id: ::std::string::String = __d.take_string()?.to_owned();
            let amount: i64 = __d.take_i64()?;
            let fee: i64 = __d.take_i64()?;
            let date: i32 = __d.take_i32()?;
            let peer: ::std::boxed::Box<rtd_tg::WalletTransactionPeer> = {
                __d.enter()?;
                let value = {
                    let __id = __d.take_u32()?;
                    decode_wallet_transaction_peer_profile(profile, __id, __d)?
                };
                __d.leave();
                ::std::boxed::Box::new(value)
            };
            let comment: Option<::std::string::String> = if flags & (1u32 << 3) != 0 {
                Some(__d.take_string()?.to_owned())
            } else {
                None
            };
            let tx_hash: Option<::std::string::String> = if flags & (1u32 << 4) != 0 {
                Some(__d.take_string()?.to_owned())
            } else {
                None
            };
            let nft: Option<::std::boxed::Box<rtd_tg::WalletNftItem>> = if flags & (1u32 << 7) != 0
            {
                Some({
                    __d.enter()?;
                    let value = {
                        let __id = __d.take_u32()?;
                        decode_wallet_nft_item_profile(profile, __id, __d)?
                    };
                    __d.leave();
                    ::std::boxed::Box::new(value)
                })
            } else {
                None
            };
            Ok(rtd_tg::WalletTransaction {
                flags,
                incoming,
                gasless,
                failed,
                key_change,
                comment_encrypted,
                id,
                amount,
                fee,
                date,
                peer,
                comment,
                tx_hash,
                nft,
            })
        }
        _ => Err(AdmitError::UnsupportedRoute(route)),
    }
}

