pub fn encode_bots_access_settings_profile(
    profile: Profile,
    value: &rtd_tg::BotsAccessSettings,
    __w: &mut Writer,
) -> Result<(), ProjectionError> {
    let route = lookup_route_semantic(profile, SemanticId(0xdbca8ce68d92c8f5)).ok_or(
        ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0xdd1fbf93,
        },
    )?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => {
            __w.put_u32(route.wire_id);
            let rtd_tg::BotsAccessSettings {
                flags,
                restricted,
                add_users,
            } = value;
            let mut __flags_flags = *flags & !0x00000003u32;
            if *restricted {
                __flags_flags |= 1u32 << 0;
            }
            if add_users.is_some() {
                __flags_flags |= 1u32 << 1;
            }
            __w.put_u32(__flags_flags);
            if let Some(value) = add_users {
                __w.put_vector_header(value.len());
                for item in value.iter() {
                    item.encode(__w);
                }
            }
            Ok(())
        }
        RouteMode::Rewrite => {
            __w.put_u32(route.wire_id);
            let rtd_tg::BotsAccessSettings {
                flags,
                restricted,
                add_users,
            } = value;
            let mut __flags_flags = *flags & !0x00000003u32;
            if *restricted {
                __flags_flags |= 1u32 << 0;
            }
            if add_users.is_some() {
                __flags_flags |= 1u32 << 1;
            }
            __w.put_u32(__flags_flags);
            if let Some(value) = add_users {
                let mut __items: ::std::vec::Vec<::std::vec::Vec<u8>> = ::std::vec::Vec::new();
                for item in value.iter() {
                    let mut __buf = Writer::with_capacity(16);
                    match encode_user_profile(profile, item, &mut __buf) {
                        Ok(()) => __items.push(__buf.into_vec()),
                        Err(ProjectionError::Dropped) => {}
                        Err(error) => return Err(error),
                    }
                }
                __w.put_vector_header(__items.len());
                for __item in &__items {
                    __w.put_raw(__item);
                }
            }
            Ok(())
        }
        _ => Err(ProjectionError::RouteNotEmitted(route)),
    }
}

pub fn decode_bots_access_settings_profile(
    profile: Profile,
    id: u32,
    __d: &mut Decoder<'_>,
) -> Result<rtd_tg::BotsAccessSettings, AdmitError> {
    let route =
        lookup_route(profile, id).ok_or(AdmitError::Decode(::rtd_bin::Error::UnexpectedId {
            id,
            expected: 0,
        }))?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => Ok(rtd_tg::BotsAccessSettings::decode_with_id(
            __d,
            canonical_wire_id(route.semantic).unwrap_or(id),
        )?),
        RouteMode::Rewrite => {
            let flags = __d.take_u32()?;
            let restricted: bool = flags & (1u32 << 0) != 0;
            let add_users: Option<::std::vec::Vec<rtd_tg::User>> = if flags & (1u32 << 1) != 0 {
                Some({
                    let n = __d.take_vector_header()?;
                    let mut items = ::std::vec::Vec::with_capacity(::rtd_bin::preallocate_len(n));
                    for _ in 0..n {
                        items.push({
                            __d.enter()?;
                            let value = {
                                let __id = __d.take_u32()?;
                                decode_user_profile(profile, __id, __d)?
                            };
                            __d.leave();
                            value
                        });
                    }
                    items
                })
            } else {
                None
            };
            Ok(rtd_tg::BotsAccessSettings {
                flags,
                restricted,
                add_users,
            })
        }
        _ => Err(AdmitError::UnsupportedRoute(route)),
    }
}

