pub fn encode_auth_sign_up_profile(
    profile: Profile,
    value: &rtd_tg::AuthSignUp,
    __w: &mut Writer,
) -> Result<(), ProjectionError> {
    let route = lookup_route_semantic(profile, SemanticId(0x60d4415ff2de9f10)).ok_or(
        ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0xaac7b717,
        },
    )?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => {
            __w.put_u32(route.wire_id);
            let rtd_tg::AuthSignUp {
                flags,
                no_joined_notifications,
                phone_number,
                phone_code_hash,
                first_name,
                last_name,
            } = value;
            let mut __flags_flags = *flags & !0x00000001u32;
            if *no_joined_notifications {
                __flags_flags |= 1u32 << 0;
            }
            __w.put_u32(__flags_flags);
            __w.put_string(phone_number.as_str());
            __w.put_string(phone_code_hash.as_str());
            __w.put_string(first_name.as_str());
            __w.put_string(last_name.as_str());
            Ok(())
        }
        RouteMode::Rewrite => {
            __w.put_u32(route.wire_id);
            let rtd_tg::AuthSignUp {
                flags,
                no_joined_notifications,
                phone_number,
                phone_code_hash,
                first_name,
                last_name,
            } = value;
            let mut __flags_flags = *flags & !0x00000001u32;
            if *no_joined_notifications {
                __flags_flags |= 1u32 << 0;
            }
            __w.put_u32(__flags_flags);
            __w.put_string(phone_number.as_str());
            __w.put_string(phone_code_hash.as_str());
            __w.put_string(first_name.as_str());
            __w.put_string(last_name.as_str());
            Ok(())
        }
        _ => Err(ProjectionError::RouteNotEmitted(route)),
    }
}

