pub fn encode_auth_sign_in_profile(
    profile: Profile,
    value: &rtd_tg::AuthSignIn,
    __w: &mut Writer,
) -> Result<(), ProjectionError> {
    let route = lookup_route_semantic(profile, SemanticId(0x34f332c6f6a4aa5c)).ok_or(
        ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0x8d52a951,
        },
    )?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => {
            __w.put_u32(route.wire_id);
            let rtd_tg::AuthSignIn {
                flags,
                phone_number,
                phone_code_hash,
                phone_code,
                email_verification,
            } = value;
            let mut __flags_flags = *flags & !0x00000003u32;
            if phone_code.is_some() {
                __flags_flags |= 1u32 << 0;
            }
            if email_verification.is_some() {
                __flags_flags |= 1u32 << 1;
            }
            __w.put_u32(__flags_flags);
            __w.put_string(phone_number.as_str());
            __w.put_string(phone_code_hash.as_str());
            if let Some(value) = phone_code {
                __w.put_string(value.as_str());
            }
            if let Some(value) = email_verification {
                value.encode(__w);
            }
            Ok(())
        }
        RouteMode::Rewrite => {
            __w.put_u32(route.wire_id);
            let rtd_tg::AuthSignIn {
                flags,
                phone_number,
                phone_code_hash,
                phone_code,
                email_verification,
            } = value;
            let mut __flags_flags = *flags & !0x00000003u32;
            if phone_code.is_some() {
                __flags_flags |= 1u32 << 0;
            }
            if email_verification.is_some() {
                __flags_flags |= 1u32 << 1;
            }
            __w.put_u32(__flags_flags);
            __w.put_string(phone_number.as_str());
            __w.put_string(phone_code_hash.as_str());
            if let Some(value) = phone_code {
                __w.put_string(value.as_str());
            }
            if let Some(value) = email_verification {
                encode_email_verification_profile(profile, value, __w)?;
            }
            Ok(())
        }
        _ => Err(ProjectionError::RouteNotEmitted(route)),
    }
}

pub fn decode_auth_sign_in_profile(
    profile: Profile,
    id: u32,
    __d: &mut Decoder<'_>,
) -> Result<rtd_tg::AuthSignIn, AdmitError> {
    let route =
        lookup_route(profile, id).ok_or(AdmitError::Decode(::rtd_bin::Error::UnexpectedId {
            id,
            expected: 0,
        }))?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => Ok(rtd_tg::AuthSignIn::decode_with_id(
            __d,
            canonical_wire_id(route.semantic).unwrap_or(id),
        )?),
        RouteMode::Rewrite => {
            let flags = __d.take_u32()?;
            let phone_number: ::std::string::String = __d.take_string()?.to_owned();
            let phone_code_hash: ::std::string::String = __d.take_string()?.to_owned();
            let phone_code: Option<::std::string::String> = if flags & (1u32 << 0) != 0 {
                Some(__d.take_string()?.to_owned())
            } else {
                None
            };
            let email_verification: Option<::std::boxed::Box<rtd_tg::EmailVerification>> =
                if flags & (1u32 << 1) != 0 {
                    Some({
                        __d.enter()?;
                        let value = {
                            let __id = __d.take_u32()?;
                            decode_email_verification_profile(profile, __id, __d)?
                        };
                        __d.leave();
                        ::std::boxed::Box::new(value)
                    })
                } else {
                    None
                };
            Ok(rtd_tg::AuthSignIn {
                flags,
                phone_number,
                phone_code_hash,
                phone_code,
                email_verification,
            })
        }
        _ => Err(AdmitError::UnsupportedRoute(route)),
    }
}

