pub fn encode_messages_report_spam_profile(
    profile: Profile,
    value: &rtd_tg::MessagesReportSpam,
    __w: &mut Writer,
) -> Result<(), ProjectionError> {
    let route = lookup_route_semantic(profile, SemanticId(0xcf70b0fe69ccf012)).ok_or(
        ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0xcf1592db,
        },
    )?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => {
            __w.put_u32(route.wire_id);
            let rtd_tg::MessagesReportSpam { peer } = value;
            peer.encode(__w);
            Ok(())
        }
        RouteMode::Rewrite => {
            __w.put_u32(route.wire_id);
            let rtd_tg::MessagesReportSpam { peer } = value;
            encode_input_peer_profile(profile, peer, __w)?;
            Ok(())
        }
        _ => Err(ProjectionError::RouteNotEmitted(route)),
    }
}

