pub fn encode_messages_report_profile(
    profile: Profile,
    value: &rtd_tg::MessagesReport,
    __w: &mut Writer,
) -> Result<(), ProjectionError> {
    let route = lookup_route_semantic(profile, SemanticId(0xe9fb9add728772bc)).ok_or(
        ProjectionError::Unrepresentable {
            layer: profile.layer,
            wire_id: 0xfc78af9b,
        },
    )?;
    match route.mode {
        RouteMode::Direct | RouteMode::Retag => {
            __w.put_u32(route.wire_id);
            let rtd_tg::MessagesReport {
                peer,
                id,
                option,
                message,
            } = value;
            peer.encode(__w);
            __w.put_vector_header(id.len());
            for item in id.iter() {
                __w.put_i32(*item);
            }
            __w.put_bytes(option.as_slice());
            __w.put_string(message.as_str());
            Ok(())
        }
        RouteMode::Rewrite => {
            __w.put_u32(route.wire_id);
            let rtd_tg::MessagesReport {
                peer,
                id,
                option,
                message,
            } = value;
            encode_input_peer_profile(profile, peer, __w)?;
            __w.put_vector_header(id.len());
            for item in id.iter() {
                __w.put_i32(*item);
            }
            __w.put_bytes(option.as_slice());
            __w.put_string(message.as_str());
            Ok(())
        }
        _ => Err(ProjectionError::RouteNotEmitted(route)),
    }
}

