#[cfg(test)]
mod generated_tests {
    use super::*;

    #[test]
    fn profile_resolution_is_fail_closed() {
        assert!(resolve_profile(CANONICAL_LAYER).is_some());
        assert!(resolve_profile(CANONICAL_LAYER + 1).is_none());
        assert_eq!(
            resolve_profile(CANONICAL_LAYER).unwrap().layer(),
            CANONICAL_LAYER
        );
    }

    #[test]
    fn routes_are_loaded() {
        assert!(!PROFILES.is_empty());
        for route in ROUTES {
            assert!(PROFILES.contains(&route.profile));
            assert!(lookup_route(Profile::new(route.profile), route.wire_id).is_some());
        }
    }
}
